[
  {
    "statement": "Several approaches show evidence for mitigating environmental pollution from salmon farming.",
    "citations": []
  },
  {
    "statement": "Fallowing periods demonstrate effectiveness in mitigating pollution from salmon farming.",
    "citations": [
      "1027",
      "2191"
    ]
  },
  {
    "statement": "A trial in Tasmania found that sediment community structure under Atlantic salmon cages became more similar to non-impacted sites over two fallowing cycles.",
    "citations": [
      "1027"
    ]
  },
  {
    "statement": "Three studies on leaving fallow periods during fish farming found that after fallowing, invertebrate community composition became similar to the composition before fish were added.",
    "citations": [
      "2191"
    ]
  },
  {
    "statement": "After fallowing periods in fish farming, the abundances of pollution-indicator polychaete worms decreased.",
