[
  {
    "statement": "Several husbandry practices beyond feed and chemical treatments can improve fish health on Atlantic salmon farms.",
    "citations": []
  },
  {
    "statement": "Fallowing systems can reduce parasites and disease.",
    "citations": []
  },
  {
    "statement": "A study in Scotland recorded lower lice numbers on Atlantic salmon in cages using fallowing.",
    "citations": [
      "1026"
    ]
  },
  {
    "statement": "Fallowing also helps reduce pollution.",
    "citations": []
  },
  {
    "statement": "A trial in Tasmania found sediment community structure under Atlantic salmon cages became more similar to non-impacted sites over two fallowing cycles.",
    "citations": [
      "1027"
    ]
  },
  {
    "statement": "Vaccination programs show effectiveness.",
    "citations": []
  },
  {
    "statement": "Controlled studies from Iceland and Norway found higher survival rates in vaccinated salmon compared to unvaccinated control groups when exposed to disease-causing bacteria.",
    "citations": [
      "733"
    ]
  },
  {
    "statement": "Infrastructure maintenance is important.",
    "citations": []
  },
  {
    "statement": "Replacing anti-predator nets more frequently at salmon farms resulted in fewer salmon losses to harbor seal predation.",
    "citations": [
      "2774"
    ]
  },
  {
    "statement": "Selective breeding for disease resistance traits can improve health outcomes.",
    "citations": []
  },
  {
    "statement": "A study in Norway found increased survival levels in salmon exposed to infectious pancreatic necrosis when the salmon's family was bred for high resistance compared to low resistance.",
    "citations": [
      "735"
    ]
  },
  {
    "statement": "The use of probiotics and immunostimulants also shows promise.",
    "citations": []
  },
  {
    "statement": "A study in Scotland found increased survival in salmon fed probiotics before exposure to disease-causing bacteria.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "A Norwegian study showed reduced lice infections when salmon were fed diets with beta-glucans.",
    "citations": [
      "732"
    ]
  }
]

[
  {
    "statement": "Several non-pesticide interventions show effectiveness for controlling sea lice on farmed salmon.",
    "citations": []
  },
  {
    "statement": "Cleaner wrasse, which are natural control agents, show mixed effectiveness in controlling sea lice.",
    "citations": [
      "738"
    ]
  },
  {
    "statement": "A controlled study in Ireland found that corkwing and goldskinny cleaner wrasse were as effective at controlling lice infestation as chemical treatments.",
    "citations": [
      "738"
    ]
  },
  {
    "statement": "The same Irish study found that rockcook cleaner wrasse were ineffective at preventing lice outbreaks.",
    "citations": [
      "738"
    ]
  },
  {
    "statement": "Lighting alteration appears to be a consistently effective method for controlling sea lice on farmed salmon.",
    "citations": [
      "741"
    ]
  },
  {
    "statement": "A study in Norway reported lower numbers of lice on salmon kept in low-intensity artificial light or natural lighting.",
    "citations": [
      "741"
    ]
  },
  {
    "statement": "The Norwegian study found that higher intensity artificial light correlated with higher lice numbers on salmon.",
    "citations": [
      "741"
    ]
  },
  {
    "statement": "Dietary interventions show promise for controlling sea lice on farmed salmon.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "A study in Norway found that salmon fed a diet of fish meal and 28% plant-based protein had 28% reduced lice infection levels.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "Adding beta-glucans to the salmon diet decreased lice infection levels by a further 28% compared with controls.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "Fallowing systems demonstrate effectiveness in controlling sea lice on farmed salmon.",
    "citations": [
      "1026"
    ]
  },
  {
    "statement": "A study in Scotland recorded lower lice numbers on Atlantic salmon in cages that used a fallowing system.",
    "citations": [
      "1026"
    ]
  },
  {
    "statement": "Probiotics show potential as a non-pesticide intervention for farmed salmon.",
    "citations": [
      "732"
    ]
  },
  {
    "statement": "One replicated study in Scotland found increased survival in salmon fed a probiotic before exposure to disease-causing bacteria.",
    "citations": [
      "732"
    ]
  }
]

